-- Runtime qualification queries: approval stale lease, single-use nonce, active policy overlap
SELECT APPROVAL_REQUEST_ID,COMMAND_REQUEST_ID,EXECUTION_STATUS,LEASE_OWNER,LEASE_EXPIRES_AT,FENCE_TOKEN,RECOVERY_REQUIRED_YN
  FROM adm_approval_execution WHERE EXECUTION_STATUS IN ('RUNNING','UNKNOWN') ORDER BY STARTED_AT;
SELECT APPROVAL_REFERENCE,EXPIRES_AT,CONSUMED_AT,CONSUMED_BY FROM adm_approval_capability_nonce ORDER BY EXPIRES_AT;
SELECT a.ACTION_TYPE,a.POLICY_CODE,a.POLICY_VERSION,b.POLICY_CODE overlap_code,b.POLICY_VERSION overlap_version
  FROM adm_approval_policy a JOIN adm_approval_policy b ON a.ACTION_TYPE=b.ACTION_TYPE
   AND (a.POLICY_CODE<>b.POLICY_CODE OR a.POLICY_VERSION<>b.POLICY_VERSION)
   AND a.ENABLED_YN='Y' AND b.ENABLED_YN='Y'
   AND a.EFFECTIVE_FROM < COALESCE(b.EFFECTIVE_TO, TIMESTAMP '9999-12-31 23:59:59')
   AND b.EFFECTIVE_FROM < COALESCE(a.EFFECTIVE_TO, TIMESTAMP '9999-12-31 23:59:59');
